import{_ as o}from"./chunks/hamburger_menu.BLyto8gA.js";import{_ as e}from"./chunks/EN.P9aPnFBv.js";import{_ as i}from"./chunks/OFF.BrU7kQE-.js";import{_ as a,a as s,b as r}from"./chunks/Diabox3.B9uDiRm7.js";import{_ as n,o as l,c as p,a3 as c}from"./chunks/framework.g9mfNVRQ.js";const k=JSON.parse('{"title":"Nightscout follower","description":"","frontmatter":{},"headers":[],"relativePath":"install/nightscoutfollower.md","filePath":"install/nightscoutfollower.md"}'),d={name:"install/nightscoutfollower.md"};function m(u,t,h,f,g,b){return l(),p("div",null,[...t[0]||(t[0]=[c('<div class="warning custom-block"><p class="custom-block-title">Old Android certificates</p><p>You might not be able to use this feature with phones running below Android 9 if they rely on expired certificates (<a href="https://community.letsencrypt.org/t/support-for-android-7-and-older-from-oct-2024/216446" target="_blank" rel="noreferrer">example</a>).<br> There is no workaround.</p></div><div class="admonition xdrip"><p class="admonition-title"><img src="'+o+'" style="zoom:75%;"></p><p> Settings<br>  Hardware Data Source<br>   Nightscout Follower</p></div><h3 id="nightscout" tabindex="-1">Nightscout <a class="header-anchor" href="#nightscout" aria-label="Permalink to &quot;Nightscout&quot;">​</a></h3><p>For using xDrip with data coming from your <a href="https://nightscout.github.io/" target="_blank" rel="noreferrer">Nightscout</a> site, you only need to enter your site URL.</p><div class="admonition xdripitem"><p class="admonition-title">Nightscout Follow URL</p><p> Web address for following</p></div><p>With a classic DIY Nightscout, the URL will look like this: <code>https://sitename.yourprovider.com</code><br> Do not add <code>/api/v1</code><br> Make sure to use <code>https</code> not <code>http</code></p><p>If you use a hosted service, contact the vendor for more information.</p><p>If your Nightscout site is <a href="https://nightscout.github.io/nightscout/security/" target="_blank" rel="noreferrer">secured</a>, you need to add the API_SECRET or token information.</p><p><code>https://API_SECRET@sitename.yourprovider.com</code></p><p><code>https://access_token@sitename.yourprovider.com</code></p><div class="admonition xdripitem"><p class="admonition-title">Download Treatments</p></div><p>You can also download compatible treatments from Nightscout (BG, calibrations, treatments, notes).</p><div class="admonition xdripitem"><p class="admonition-title">Download Treatments <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Also download treatments from Nightscout as follower</p></div><p>If you want to avoid the risk of data duplication (important for AAPS) you can prevent xDrip from downloading data it has been uploading to Nightscout.</p><div class="admonition xdripitem"><p class="admonition-title">Skip items from xDrip <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p><p> Avoid downloading items uploaded by xDrip</p></div><p>If you experience large delays in xDrip, you can set a fixed delay to re-synchronize it with Nightscout. Leave this at default.</p><div class="admonition xdripitem"><p class="admonition-title">Nightscout Follow delay</p><p> 0&gt;</p></div><div class="info custom-block"><p class="custom-block-title">Note</p><p>xDrip performs limited (24 hours) data backfilling from Nightscout.</p></div><p>If your Nightscout site reports device status (uploader battery, pump battery), xDrip will show it in System Status.</p><div class="info custom-block"><p class="custom-block-title">Note</p><p>Local Nightscout emulators such as <a href="https://github.com/j-kaltes/Juggluco" target="_blank" rel="noreferrer">Juggluco</a> are also supported as a follower source.</p></div><br><h3 id="diabox" tabindex="-1">Diabox <a class="header-anchor" href="#diabox" aria-label="Permalink to &quot;Diabox&quot;">​</a></h3><p>You can receive data from <a href="https://sirius.thetaphi.de/diabox/" target="_blank" rel="noreferrer">Diabox</a> by enabling http broadcast in the app and making xDrip a local follower.</p><div class="warning custom-block"><p class="custom-block-title">Warning</p><p>You cannot use this feature with xDrip running a <a href="./../use/interapp.html#web-service">web service</a>.</p></div><img src="'+a+'" style="zoom:75%;"><img src="'+s+'" style="zoom:75%;"><p>Once done, set xDrip to Nightscout follower (see above) with the address:</p><p><code>http://localhost:17580</code></p><img src="'+r+'" style="zoom:75%;"><br><p><a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2026.07.03" target="_blank" rel="noreferrer"><em>Last modified 6/7/2026</em></a></p>',31)])])}const N=n(d,[["render",m]]);export{k as __pageData,N as default};
